// Security: only ever allow reading the exact generated question-paper PDF
// filenames from a single fixed directory. Never build a path directly from
// unsanitized user input.
//
// - Only filenames matching ALLOWED_FILENAME_PATTERN are accepted.
// - '..' and any path separators are explicitly rejected (defense in depth,
//   even though the pattern below already excludes them).
// - The resolved path is always BASE_DIR + <validated filename>, never a
//   caller-supplied path.
//
// If 03_DOCUMENT_GENERATOR ever changes its output filenames, update
// ALLOWED_FILENAME_PATTERN to match - do not loosen it to a generic wildcard.
const BASE_DIR = '/data/question-papers/';
const ALLOWED_FILENAME_PATTERN = /^Question_Paper_Set_[A-Z]\.pdf$/;

const query = $input.first().json.query || {};
const requested = String(query.file || '').trim();

const isValid =
  ALLOWED_FILENAME_PATTERN.test(requested) &&
  !requested.includes('..') &&
  !requested.includes('/') &&
  !requested.includes('\\');

return [{
  json: {
    requestedFile: requested,
    isValid,
    filePath: isValid ? (BASE_DIR + requested) : null
  }
}];
